                    case EVENT_CAST_RIDE_SPELL:
                        if (Player* summoner = ObjectAccessor::GetPlayer(*me, _summonerGuid))
                            me->CastSpell(summoner, SPELL_RIDE_RED_DRAGON_TRIGGERED, true);
                        else
                            me->DespawnOrUnsummon();
                        break;
                }
            }
        }

        void PassengerBoarded(Unit* player, int8 /*seat*/, bool apply) override
        {
            if (!apply)
            {
                me->DespawnOrUnsummon(2050);
                me->SetOrientation(2.5f);
                me->SetSpeed(MOVE_FLIGHT, 1.0f, true);
                Position pos = me->GetPosition();
                pos.m_positionX += 10.0f;
                pos.m_positionY += 10.0f;
                pos.m_positionZ += 12.0f;
                me->GetMotionMaster()->MovePoint(1, pos);
            }
            player->ClearUnitState(UNIT_STATE_ONVEHICLE);
        }

    private:
        ObjectGuid _summonerGuid;
        EventMap _events;
    }

